// Define a type alias for the Matrix
type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract the number of rows (R) and columns (C) from the shape
    let r = shape[0] as usize; // Convert from u8 to usize
    let c = shape[1] as usize; // Convert from u8 to usize

    // Initialize the matrix with the specified shape
    let mut matrix: Matrix<i8> = vec![vec![0; c]; r];

    // Check if the array length matches R or C
    if a.len() == r {
        // Treat `a` as a column vector
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[i]; // Fill each row with the corresponding element from `a`
            }
        }
    } else if a.len() == c {
        // Treat `a` as a row vector
        for i in 0..r {
            for j in 0..c {
                matrix[i][j] = a[j]; // Fill each row with the elements from `a`
            }
        }
    } else {
        // This case should not happen due to the problem's assumptions
        panic!("The length of the array does not match the shape dimensions.");
    }

    matrix
}